mkdir -p android && sed "s|^storeFile=\(.*\)|storeFile=../\1|" key.properties > android/key.properties && python3 -c 'import os, re; bg="android/app/build.gradle"; (lambda c: open(bg,"w").write("def keystoreProperties = new Properties()
def keystorePropertiesFile = rootProject.file("key.properties")
if (keystorePropertiesFile.exists()) {
    keystoreProperties.load(new FileInputStream(keystorePropertiesFile))
}

" + re.sub(r"buildTypes\s*\{", "signingConfigs {
        release {
            keyAlias = keystoreProperties["keyAlias"]
            keyPassword = keystoreProperties["keyPassword"]
            storeFile = keystoreProperties["storeFile"] ? file(keystoreProperties["storeFile"]) : null
            storePassword = keystoreProperties["storePassword"]
        }
    }

    buildTypes {", re.sub(r"signingConfig\s*=\s*signingConfigs\.debug", "signingConfig = signingConfigs.release", c))) if os.path.exists(bg) and "keystoreProperties" not in c else None)(open(bg).read() if os.path.exists(bg) else "")' && echo "Keystore fully linked to Android successfully!"
